# Sources/stage2_dataset.py
#
# Stage-2 latent-database dataset:
#   geometry/material parameters -> latent vector z
#
# What it does:
# 1) Loads the latent database CSV/NPZ generated by the frozen Stage-1 CNN-AE.
# 2) Uses 17 geometry/material parameters as input.
# 3) Uses z_0 ... z_59 as target latent vector.
# 4) Performs random 70/20/10 split.
# 5) Fits X and z scalers on TRAIN ONLY to avoid leakage.
#
# Stage-2 sample format:
#   x_norm  : Tensor [P]
#   z_norm  : Tensor [latent_dim]
#   row_idx : int, original database row index
#   sid     : int, simulation ID

from __future__ import annotations

import os
from dataclasses import dataclass
from typing import Dict, List, Optional, Tuple, Any

import numpy as np
import pandas as pd
import torch
from torch.utils.data import Dataset, DataLoader
from sklearn.model_selection import train_test_split
from sklearn.preprocessing import StandardScaler


DEFAULT_GEO_COLS = [
    "TDIEL", "TMET", "XWIDTH", "YWIDTH",
    "CONDUCTIVITY", "PERMITTIVITY", "LOSSTANGENT",
    "A1_VIARADIUS", "A1_ANTIPADRADIUS", "A1_VIAPITCH",
    "A1_XCENTER", "A1_YCENTER",
    "A2_VIARADIUS", "A2_ANTIPADRADIUS", "A2_VIAPITCH",
    "A2_XCENTER", "A2_YCENTER",
]


@dataclass
class Stage2DataBundle:
    train_loader: DataLoader
    val_loader: DataLoader
    test_loader: DataLoader

    x_scaler: StandardScaler
    z_scaler: StandardScaler

    feature_cols: List[str]
    z_cols: List[str]
    split_info: Dict[str, Any]

    db_df: pd.DataFrame
    X_raw: np.ndarray
    Z_raw: np.ndarray
    SID: np.ndarray
    GEO: np.ndarray
    freq_hz: np.ndarray

    idx_train: np.ndarray
    idx_val: np.ndarray
    idx_test: np.ndarray


class Stage2LatentDataset(Dataset):
    """
    Dataset for Stage-2 supervised regression:
        input  : normalized geometry/material vector x [P]
        target : normalized latent vector z [latent_dim]
        row_idx: original row index in latent database
        sid    : simulation ID
    """

    def __init__(
        self,
        X_norm: np.ndarray,
        Z_norm: np.ndarray,
        SID: np.ndarray,
        indices: np.ndarray,
    ):
        self.X = torch.as_tensor(X_norm[indices], dtype=torch.float32)
        self.Z = torch.as_tensor(Z_norm[indices], dtype=torch.float32)
        self.indices = np.asarray(indices, dtype=np.int64)
        self.SID = np.asarray(SID, dtype=np.int64)[indices]

    def __len__(self):
        return len(self.indices)

    def __getitem__(self, idx):
        return self.X[idx], self.Z[idx], int(self.indices[idx]), int(self.SID[idx])


def _find_latent_columns(db_df: pd.DataFrame, latent_dim: Optional[int] = 60) -> List[str]:
    z_cols = [c for c in db_df.columns if c.startswith("z_")]
    z_cols = sorted(z_cols, key=lambda x: int(x.split("_")[1]))

    if latent_dim is not None:
        expected = [f"z_{i}" for i in range(latent_dim)]
        missing = [c for c in expected if c not in db_df.columns]
        if missing:
            raise ValueError(f"Missing latent columns in CSV: {missing[:10]}")
        z_cols = expected

    if len(z_cols) == 0:
        raise ValueError("No latent columns z_0, z_1, ... found in CSV.")

    return z_cols


def _select_feature_columns(
    db_df: pd.DataFrame,
    npz_geometry: np.ndarray,
    feature_cols: Optional[List[str]] = None,
) -> Tuple[np.ndarray, List[str]]:

    if feature_cols is not None:
        missing = [c for c in feature_cols if c not in db_df.columns]
        if missing:
            raise ValueError(f"Requested feature columns missing in CSV: {missing}")
        return db_df[feature_cols].values.astype(np.float32), feature_cols

    if all(c in db_df.columns for c in DEFAULT_GEO_COLS):
        return db_df[DEFAULT_GEO_COLS].values.astype(np.float32), DEFAULT_GEO_COLS

    fallback_cols = [f"geo_{i}" for i in range(npz_geometry.shape[1])]
    return npz_geometry.astype(np.float32), fallback_cols


def load_stage2_arrays(
    csv_path: str,
    npz_path: str,
    latent_dim: Optional[int] = 60,
    feature_cols: Optional[List[str]] = None,
):
    """
    Load Stage-1 latent database and verify CSV/NPZ consistency.
    """
    if not os.path.exists(csv_path):
        raise FileNotFoundError(f"CSV not found: {csv_path}")
    if not os.path.exists(npz_path):
        raise FileNotFoundError(f"NPZ not found: {npz_path}")

    db_df = pd.read_csv(csv_path)
    npz = np.load(npz_path)

    required_keys = ["latents", "simu_ids", "geometry", "freq_hz"]
    missing_keys = [k for k in required_keys if k not in npz.files]
    if missing_keys:
        raise ValueError(f"NPZ missing required keys: {missing_keys}. Found keys: {npz.files}")

    Z_npz = npz["latents"].astype(np.float32)
    SID = npz["simu_ids"].astype(np.int64)
    GEO = npz["geometry"].astype(np.float32)
    freq_hz = npz["freq_hz"].astype(np.float64)

    if "simu_index" not in db_df.columns:
        raise ValueError("CSV must contain 'simu_index' column.")

    if len(db_df) != len(SID) or len(db_df) != len(Z_npz):
        raise ValueError(f"Length mismatch: CSV={len(db_df)}, SID={len(SID)}, Z={len(Z_npz)}")

    csv_sids = db_df["simu_index"].values.astype(np.int64)
    if not np.all(csv_sids == SID):
        raise ValueError("CSV simu_index and NPZ simu_ids do not match in same order.")

    z_cols = _find_latent_columns(db_df, latent_dim=latent_dim)
    Z_csv = db_df[z_cols].values.astype(np.float32)

    max_abs_diff = float(np.max(np.abs(Z_csv - Z_npz[:, :len(z_cols)])))
    if max_abs_diff > 1e-4:
        raise ValueError(f"CSV and NPZ latent values differ too much: max_abs_diff={max_abs_diff}")

    X_raw, used_feature_cols = _select_feature_columns(
        db_df=db_df,
        npz_geometry=GEO,
        feature_cols=feature_cols,
    )

    return db_df, X_raw, Z_npz[:, :len(z_cols)], SID, GEO, freq_hz, used_feature_cols, z_cols


def make_stage2_dataloaders(
    csv_path: str,
    npz_path: str,
    latent_dim: int = 60,
    feature_cols: Optional[List[str]] = None,
    batch_size: int = 256,
    seed: int = 42,

    # Default split: 70/20/10
    train_fraction: float = 0.70,
    val_fraction: float = 0.20,
    test_fraction: float = 0.10,

    num_workers: int = 0,
    pin_memory: bool = False,
) -> Stage2DataBundle:
    """
    Build leakage-free Stage-2 train/val/test loaders.
    Scalers are fit on TRAIN ONLY.
    Split is random but deterministic with seed.
    """
    if abs(train_fraction + val_fraction + test_fraction - 1.0) > 1e-8:
        raise ValueError("train_fraction + val_fraction + test_fraction must sum to 1.")

    db_df, X_raw, Z_raw, SID, GEO, freq_hz, used_feature_cols, z_cols = load_stage2_arrays(
        csv_path=csv_path,
        npz_path=npz_path,
        latent_dim=latent_dim,
        feature_cols=feature_cols,
    )

    idx_all = np.arange(len(X_raw))

    # First split: train vs temp
    idx_train, idx_temp = train_test_split(
        idx_all,
        test_size=(val_fraction + test_fraction),
        random_state=seed,
        shuffle=True,
    )

    # Second split: val vs test
    rel_test = test_fraction / (val_fraction + test_fraction)

    idx_val, idx_test = train_test_split(
        idx_temp,
        test_size=rel_test,
        random_state=seed,
        shuffle=True,
    )

    x_scaler = StandardScaler()
    z_scaler = StandardScaler()

    X_norm = np.empty_like(X_raw, dtype=np.float32)
    Z_norm = np.empty_like(Z_raw, dtype=np.float32)

    X_norm[idx_train] = x_scaler.fit_transform(X_raw[idx_train]).astype(np.float32)
    X_norm[idx_val] = x_scaler.transform(X_raw[idx_val]).astype(np.float32)
    X_norm[idx_test] = x_scaler.transform(X_raw[idx_test]).astype(np.float32)

    Z_norm[idx_train] = z_scaler.fit_transform(Z_raw[idx_train]).astype(np.float32)
    Z_norm[idx_val] = z_scaler.transform(Z_raw[idx_val]).astype(np.float32)
    Z_norm[idx_test] = z_scaler.transform(Z_raw[idx_test]).astype(np.float32)

    train_ds = Stage2LatentDataset(X_norm, Z_norm, SID, idx_train)
    val_ds = Stage2LatentDataset(X_norm, Z_norm, SID, idx_val)
    test_ds = Stage2LatentDataset(X_norm, Z_norm, SID, idx_test)

    train_loader = DataLoader(
        train_ds,
        batch_size=batch_size,
        shuffle=True,
        num_workers=num_workers,
        pin_memory=pin_memory,
    )

    val_loader = DataLoader(
        val_ds,
        batch_size=batch_size,
        shuffle=False,
        num_workers=num_workers,
        pin_memory=pin_memory,
    )

    test_loader = DataLoader(
        test_ds,
        batch_size=batch_size,
        shuffle=False,
        num_workers=num_workers,
        pin_memory=pin_memory,
    )

    split_info = {
        "n_total": int(len(idx_all)),
        "n_train": int(len(idx_train)),
        "n_val": int(len(idx_val)),
        "n_test": int(len(idx_test)),
        "train_fraction": float(train_fraction),
        "val_fraction": float(val_fraction),
        "test_fraction": float(test_fraction),
        "seed": int(seed),
        "split_type": "random",
        "input_dim": int(X_raw.shape[1]),
        "latent_dim": int(Z_raw.shape[1]),
        "feature_cols": used_feature_cols,
        "z_cols": z_cols,
        "train_sids": SID[idx_train].astype(int).tolist(),
        "val_sids": SID[idx_val].astype(int).tolist(),
        "test_sids": SID[idx_test].astype(int).tolist(),
    }

    return Stage2DataBundle(
        train_loader=train_loader,
        val_loader=val_loader,
        test_loader=test_loader,
        x_scaler=x_scaler,
        z_scaler=z_scaler,
        feature_cols=used_feature_cols,
        z_cols=z_cols,
        split_info=split_info,
        db_df=db_df,
        X_raw=X_raw,
        Z_raw=Z_raw,
        SID=SID,
        GEO=GEO,
        freq_hz=freq_hz,
        idx_train=idx_train,
        idx_val=idx_val,
        idx_test=idx_test,
    )